"""Write `operations.py` from the enriched OpenAPI document, and `metric_names.py` and `job_container.py`."""

from __future__ import annotations

import argparse
import json
import re
from pathlib import Path
from typing import Any

from ccf_api_models.contracts import JobContainerContract, MetricsContract
from pydantic.alias_generators import to_snake

_HEADER = (
    '"""Generated by `codegen/write_enums.py` from {source}. Do not edit."""\n\nfrom __future__ import annotations\n'
)
_REQUEST_MODEL_EXTENSION = "x-ccf-request-model"
_SCHEMAS = "#/components/schemas/"


class OperationsWriter:
    """Writes `Operation`, `OPERATION_MODELS`, and the `CcfApi` protocol, sorted by `operationId`."""

    def write(self, openapi: dict[str, Any]) -> str:
        operations = sorted(
            (
                str(operation["operationId"]),
                str(operation[_REQUEST_MODEL_EXTENSION]),
                self._response_model(operation),
            )
            for path_item in openapi["paths"].values()
            for operation in path_item.values()
        )
        models = sorted({model for _, request, response in operations for model in (request, response) if model})
        lines = [
            _HEADER.format(source="`openapi.json`"),
            "from enum import StrEnum",
            "from typing import Final, Protocol, overload",
            "",
            "from ccf_api_models.base import CcfModel, ValueModel",
            "from ccf_api_models.models import (",
            *(f"    {model}," for model in models),
            ")",
            "",
            "",
            "class Operation(StrEnum):",
            *(f'    {self._member_name(name)} = "{name}"' for name, _, _ in operations),
            "",
            "",
            "class OperationModels(ValueModel):",
            "    request: type[CcfModel]",
            "    response: type[CcfModel] | None",
            '    """None when the operation returns no body."""',
            "",
            "",
            "OPERATION_MODELS: Final[dict[Operation, OperationModels]] = {",
            *(
                f"    Operation.{self._member_name(name)}: OperationModels(request={request}, response={response}),"
                for name, request, response in operations
            ),
            "}",
            "",
            "",
            "class CcfApi(Protocol):",
            '    """A client with one typed `call` per operation."""',
            "",
        ]
        for _, request, response in operations:
            lines += ["    @overload", f"    def call(self, request: {request}) -> {response}: ...", ""]
        lines.append("    def call(self, request: CcfModel) -> CcfModel | None: ...")
        return "\n".join(lines) + "\n"

    @staticmethod
    def _member_name(operation_id: str) -> str:
        return re.sub(r"(?<!^)(?=[A-Z])", "_", operation_id).upper()

    @staticmethod
    def _response_model(operation: dict[str, Any]) -> str | None:
        [success] = [response for status, response in operation["responses"].items() if status.startswith("2")]
        if "content" not in success:
            return None
        return str(success["content"]["application/json"]["schema"]["$ref"]).removeprefix(_SCHEMAS)


class MetricNamesWriter:
    """Writes the metrics namespace, `MetricName`, and `MetricDimensionName`."""

    def write(self, contract: MetricsContract) -> str:
        lines = [
            _HEADER.format(source="`contracts/metrics.json`"),
            "from enum import StrEnum",
            "from typing import Final",
            "",
            f'METRICS_NAMESPACE: Final = "{contract.namespace}"',
            "",
            "",
            "class MetricName(StrEnum):",
            *(f'    {key} = "{metric.name}"' for key, metric in sorted(contract.metrics.items())),
            "",
            "",
            "class MetricDimensionName(StrEnum):",
            *(f'    {key} = "{name}"' for key, name in sorted(contract.dimensions.items())),
        ]
        return "\n".join(lines) + "\n"


class JobContainerWriter:
    """Writes the job's container names, `RuntimeVariable`, and `JobExitCode`."""

    def write(self, contract: JobContainerContract) -> str:
        lines = [
            _HEADER.format(source="`contracts/job_container.json`"),
            "from enum import IntEnum, StrEnum",
            "from typing import Final",
            "",
            f'CONNECTOR_CONTAINER: Final = "{contract.containers.connector}"',
            f'LOG_ROUTER_CONTAINER: Final = "{contract.containers.log_router}"',
            "",
            "",
            "class RuntimeVariable(StrEnum):",
            '    """The connector container\'s environment variables."""',
            "",
            *(f'    {to_snake(key).upper()} = "{name}"' for key, name in contract.variables.items()),
            "",
            "",
            "class JobExitCode(IntEnum):",
            '    """How a job container ended."""',
            "",
            *(f"    {name} = {code}" for name, code in contract.exit_codes.items()),
        ]
        return "\n".join(lines) + "\n"


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--openapi", type=Path, required=True)
    parser.add_argument("--operations", type=Path, required=True)
    parser.add_argument("--metric-names", type=Path, required=True)
    parser.add_argument("--job-container", type=Path, required=True)
    arguments = parser.parse_args()

    openapi = json.loads(arguments.openapi.read_text(encoding="utf-8"))
    arguments.operations.write_text(OperationsWriter().write(openapi), encoding="utf-8")
    arguments.metric_names.write_text(MetricNamesWriter().write(MetricsContract.load()), encoding="utf-8")
    arguments.job_container.write_text(JobContainerWriter().write(JobContainerContract.load()), encoding="utf-8")


if __name__ == "__main__":
    main()
